function birthdays(){return fixedSixSlots(birthdayExamples,'birthdays',n=>`<article class="panel birthday-card"><header class="birthday-card-header"><span>${esc(n.date)}</span></header><h3 class="birthday-name">Gefeliciteerd, ${esc(birthdayDisplayName(n))}!</h3><div class="birthday-age-block"><b class="birthday-age">${n.age}</b><span>JAAR</span></div><p>${esc(n.team)}</p></article>`)}
