function menuScene(){const sections=[{title:'Voor de trek.',items:[['Broodje kroket','3,00','Vers op een broodje'],['Broodje frikandel','3,00','Met of zonder saus'],['Tosti kaas','3,50','Goudbruin van de grill'],['Patat','2,75','Saus + € 0,25'],['Broodje erbij','0,50','Bij je favoriete snack']]},{title:'Voor de dorst.',items:[['Koffie / thee','2,00','Even lekker bijpraten'],['Frisdrank','2,50','Lekker koud'],['Sportdrank','2,75','Na de inspanning'],['Bier 0.0','2,75','Ook helemaal goed'],['Flesje water','2,00','Wel zo verfrissend']]}];return `<div class="menu-layout"><section class="panel">${head('WELKOM IN ONZE KANTINE','Wat mag het zijn?','food')}<div class="menu-columns">${sections.map(s=>`<div class="menu-category"><h3>${s.title}</h3>${s.items.map(i=>`<div class="price-row"><span>${i[0]}<small>${i[2]}</small></span><b>€ ${i[1]}</b></div>`).join('')}</div>`).join('')}</div>${foot('Voorbeeldprijzen · vraag aan de bar naar allergenen','Met jouw aankoop steun je de club.')}</section><section class="panel menu-feature"><div class="round-promo"><small>DE DERDE HELFT</small><b>€ 3,50</b></div><h3>Even blijven<br>is ook meedoen.</h3><p>Een tosti. Een goed gesprek.<br>En de club om je heen.</p></section></div>`}
