function pollScene(){const opts=['De sfeer langs de lijn','Het voetbal op het veld','De gezelligheid na afloop'];let percentages=state.vote===null?[42,34,24]:[42,34,24].map((p,i)=>i===state.vote?p+4:p-2);return `<div class="engage-layout"><section class="panel poll-panel"><span class="news-label">DE VRAAG VAN DE ZATERDAG</span><h3>Wat maakt jouw zaterdag op de club compleet?</h3>${opts.map((o,i)=>`<button class="poll-option ${state.vote===i?'selected':''}" data-vote="${i}" style="--percent:${percentages[i]}%"><span>${o}</span><b>${percentages[i]}%</b></button>`).join('')}<p>${state.vote===null?'Klik om de publieksactie te proberen · voorbeeldstemmen':'Jouw voorbeeldstem is verwerkt. Bedankt voor het meedoen!'}</p></section><aside class="panel engage-aside">${logo('Duindorp SV')}<h3>Jouw stem.<br>Onze club.</h3><p>Een klein gebaar.<br>Een groot clubgevoel.<br><br>Doe mee via het clubportaal.</p></aside></div>`}
