function contentFor(id){switch(id){case'matchday':return matchPanel('pool',true,true)+ranking(false,true)+matchPanel('pool',false,true);case'standings':return ranking();case'period-standings':return ranking(true);case'fixtures':case'club-program':return matchPanel('club');case'team-program':return matchPanel('team');case'pool-program':return matchPanel('pool');case'results':case'club-results':return matchPanel('club',true);case'team-results':return matchPanel('team',true);case'pool-results':return matchPanel('pool',true);case'cancellations':return cancellationScene();case'dressing-rooms':return roomScene(false,true);case'changing-rooms':return roomScene();case'team-arrivals':return roomScene(true);case'officials':return peopleScene();case'referees':return peopleScene(false,true);case'volunteers':return peopleScene(true);case'training':return trainingScene();case'team-info':return teamScene();case'activities':return eventScene();case'agenda':return eventScene(true);case'welcome':case'visitors':return welcomeScene();case'next-match':case'scoreboard':return matchHero(id);case'goal':return goalScene();case'birthdays':return birthdays();case'lineup':return lineupScene();case'menu':return menuScene();case'engage':return pollScene();case'sponsors':return sponsorScene();case'rss':return newsScene();case'club-story':return newsScene(true);case'youtube':return videoScene();case'free':return freeScene();default:throw new Error('Ontbrekende slide: '+id)}}
function brandContainerHeaders(screen){
  if(state.id!=='matchday')screen.querySelectorAll('.slide-content .panel-head').forEach(el=>el.remove());
  const wrap=label=>{if(!label||label.parentElement.classList.contains('container-inline-header'))return;const header=document.createElement('header');header.className='container-inline-header';label.replaceWith(header);header.append(label)};
  screen.querySelectorAll('.feature-copy>.eyebrow,.event-copy>.event-date,.poll-panel>.news-label').forEach(wrap);
  screen.querySelectorAll('.slide-content .container-club-logo').forEach(el=>el.remove());
  screen.querySelectorAll('.goal-scene,.free-scene,.engage-aside,.menu-feature,.video-layout,.welcome-empty').forEach(container=>[...container.children].filter(el=>el.tagName==='IMG'&&el.getAttribute('src')==='/assets/logo.png'&&!el.classList.contains('watermark')).forEach(el=>el.remove()));
}
function stageEntrance(screen){const containers=[...screen.querySelectorAll('.slide-content .panel,.slide-content .photo-panel,.slide-content .pitch,.slide-content .goal-scene,.slide-content .video-layout')].filter(el=>!el.parentElement.closest('.panel,.photo-panel,.pitch,.goal-scene,.video-layout'));containers.forEach((el,i)=>{el.classList.add('scene-container');el.style.setProperty('--scene-delay',(2.1+i*.12)+'s')});screen.style.setProperty('--scene-footer-delay',(2.6+Math.max(0,containers.length-1)*.12)+'s');screen.classList.add('scene-reset');void screen.offsetWidth;screen.classList.remove('scene-reset')}
function replayScene(){if(!matchMedia('(prefers-reduced-motion: reduce)').matches)state.motion=true;render()}
function currentHeaderText(f){return Object.prototype.hasOwnProperty.call(state.headerTexts,f.id)?state.headerTexts[f.id]:f.label}
function currentHeaderSubtitle(f){return Object.prototype.hasOwnProperty.call(state.headerSubtitles,f.id)?state.headerSubtitles[f.id]:`Duindorp SV · ${f.group}`}
function fitHeaderText(){const title=$('#slide-title'),subtitle=$('#slide-subtitle'),copy=$('#screen .slide-header-copy');if(!title||!subtitle||!copy)return;subtitle.hidden=!subtitle.textContent;title.hidden=!title.textContent;let subSize=state.portrait?11:12;subtitle.style.fontSize=subSize+'px';while(subSize>9&&subtitle.scrollHeight>30){subtitle.style.fontSize=(--subSize)+'px'}let size=state.portrait?38:42;title.style.fontSize=size+'px';const available=copy.clientHeight-(subtitle.hidden?0:subtitle.offsetHeight+7);while(size>14&&title.scrollHeight>available+1){title.style.fontSize=(--size)+'px'}}
function fitWelcomeIdentity(){const desired=state.welcomeScale/100;$$('#screen .visitor-stage').forEach(stage=>{const identity=stage.querySelector('.visitor-spotlight');if(!identity)return;const width=Math.max(identity.offsetWidth,identity.scrollWidth),height=Math.max(identity.offsetHeight,identity.scrollHeight);const fit=Math.max(.1,Math.min(desired,stage.clientWidth/Math.max(1,width),stage.clientHeight/Math.max(1,height)));identity.style.setProperty('--welcome-fit',fit);stage.dataset.effectiveScale=String(Math.round(fit*100))})}
function fitScene(){fitHeaderText();fitWelcomeIdentity()}
