function persist(){try{localStorage.setItem('onzetrots-studio',JSON.stringify({theme:state.theme,portrait:state.portrait,background:state.background,opacity:state.opacity,speed:state.speed,headerTexts:state.headerTexts,headerSubtitles:state.headerSubtitles,welcomeScale:state.welcomeScale}))}catch{}}
function renderSidebar(){const filtered=families.filter(f=>(state.group==='all'||(state.group==='other'?!['Sport','Club'].includes(f.group):f.group===state.group))&&normal(f.name+' '+f.label).includes(normal(state.query)));filtered.sort((a,b)=>{const groups=['Sport','Club','Kantine','Media','Vrij'];return groups.indexOf(a.group)-groups.indexOf(b.group)||(a.id==='matchday'?-1:b.id==='matchday'?1:families.indexOf(a)-families.indexOf(b))});let last='';$('#family-list').innerHTML=filtered.length?filtered.map(f=>{let group=f.group!==last?`<div class="group-title">${f.group.toUpperCase()}</div>`:'';last=f.group;return group+`<button class="family-btn${f.id===state.id?' active':''}" data-family="${f.id}" aria-current="${f.id===state.id?'true':'false'}">${icon(familyIcons[f.id]||'calendar')}<span>${esc(f.name)}</span><small>${String(families.indexOf(f)+1).padStart(2,'0')}</small></button>`}).join(''):'<p style="padding:15px;color:#8499b5;font-size:11px">Geen slides gevonden.</p>';$$('.filter-chips button').forEach(b=>b.classList.toggle('active',b.dataset.group===state.group))}
