function scale(){const shell=$('#screen-shell');const screen=$('#screen');screen.style.transform=`scale(${shell.clientWidth/(state.portrait?900:1600)})`}
function stopMotion(){cancelAnimationFrame(rankAnimation);pageTimers.forEach(clearInterval);pageTimers=[]}
function beginMotion(){stopMotion();const generation=renderGeneration;const lists=$$('#screen .rank-list');let last=performance.now();let elapsed=0;function frame(now){if(generation!==renderGeneration)return;const delta=Math.min(80,now-last);last=now;if(state.motion&&document.visibilityState==='visible'){elapsed+=delta/1000;const speed={slow:19,normal:30,fast:48}[state.speed];lists.forEach(el=>{const max=el.scrollHeight-el.clientHeight;const travel=max/speed;const phase=elapsed%(travel*2+5);let y;if(phase<2.5)y=0;else if(phase<2.5+travel)y=(phase-2.5)*speed;else if(phase<5+travel)y=max;else y=max-(phase-5-travel)*speed;el.scrollTop=Math.max(0,Math.min(max,y));const own=el.querySelector('.own');const factor=own.getBoundingClientRect().height/own.offsetHeight;const offset=(own.getBoundingClientRect().top-el.getBoundingClientRect().top)/factor;const status=el.closest('.panel').querySelector('.rank-status');if(status)status.textContent=offset<=2?'Duindorp · boven vast':offset>=el.clientHeight-own.offsetHeight-2?'Duindorp · onder vast':'Duindorp beweegt mee';const bar=el.closest('.panel').querySelector('.rank-progress i');if(bar)bar.style.width=(max?25+75*y/max:100)+'%';})}rankAnimation=requestAnimationFrame(frame)}if(lists.length)rankAnimation=requestAnimationFrame(frame);$$('#screen .pageable').forEach(el=>{let page=0;const rows=matchRows(el.dataset.scope,el.dataset.result==='true'),count=+el.dataset.count,pages=Math.ceil(rows.length/count);if(pages<2)return;pageTimers.push(setInterval(()=>{if(!state.motion||document.visibilityState!=='visible')return;page=(page+1)%pages;const from=page*count;el.innerHTML=rows.slice(from,from+count).map(m=>matchCard(m,el.dataset.result==='true')).join('');const panel=el.closest('.panel');panel.querySelector('.page-indicator').textContent=String(page+1).padStart(2,'0')+' / '+String(pages).padStart(2,'0');panel.querySelector('.page-status').textContent=`${from+1}–${Math.min(from+count,rows.length)} van ${rows.length}`},8000))});if(['rss','club-story'].includes(state.id))pageTimers.push(setInterval(()=>{if(state.motion&&document.visibilityState==='visible'){newsIndex++;render(false)}},12000))}
function render(resetNews=true){if(!families.some(f=>f.id===state.id))state.id='matchday';renderGeneration++;if(resetNews)newsIndex=0;const f=families.find(f=>f.id===state.id);const title=titles[f.id]||[f.name,''];const screen=$('#screen');screen.className=`screen${state.portrait?' portrait':''}${state.motion?'':' is-paused'}${matchMedia('(prefers-reduced-motion: reduce)').matches?' reduced':''}`;screen.dataset.theme=state.theme;screen.style.setProperty('--bg',`url('/assets/clubmuur-brush-v25/${state.background}-${state.portrait?'portrait-941':'wide-1672'}.webp')`);screen.style.setProperty('--panel',state.theme==='light'?`rgba(255,255,255,${state.opacity/100})`:`rgba(12,31,58,${state.opacity/100})`);screen.style.setProperty('--welcome-scale',state.welcomeScale/100);screen.innerHTML=`<div class="slide-layout with-slide-header"><header class="panel slide-header-container"><div class="slide-header-copy"><p id="slide-subtitle" class="slide-subtitle">${esc(currentHeaderSubtitle(f))}</p><h2 id="slide-title">${esc(currentHeaderText(f))}</h2></div>${containerClubLogo}</header><div class="slide-content">${contentFor(f.id)}</div><footer class="slide-footer"><span class="source">${['rss','club-story'].includes(f.id)?'Duindorp SV · Nieuws & verhalen':f.group==='Sport'?'Sportlink · Voorbeeldgegevens':'Duindorp SV · Voorbeeldinhoud'}</span><span class="signature"><span class="brand-brush" role="img" aria-label="OnzeTrots"></span><small>ONZE CLUB. ONZE TROTS.</small></span></footer></div>`;brandContainerHeaders(screen);stageEntrance(screen);$('#slide-header-text').value=currentHeaderText(f);$('#slide-subtitle-text').value=currentHeaderSubtitle(f);$('#header-editor-family').textContent=f.name;$('#welcome-scale').value=state.welcomeScale;$('#welcome-scale-value').textContent=state.welcomeScale+'%';$('#screen-shell').classList.toggle('is-portrait',state.portrait);$('#current-name').textContent=f.name;$('#current-category').textContent=f.group+' · OnzeTrots';$('#current-num').textContent=String(families.indexOf(f)+1).padStart(2,'0');$('#canvas-size').textContent=state.portrait?'1080 × 1920':'1920 × 1080';$('#detail-title').textContent=f.id==='matchday'?'Het hele eerste, op één scherm.':f.id.includes('standings')?'Onze club blijft altijd in beeld.':f.name+'. Helemaal OnzeTrots.';$('#detail-copy').textContent=['birthdays','activities','agenda'].includes(f.id)?'Vast raster van drie kolommen en twee rijen. Er zijn altijd zes plekken; niet-gevulde plekken blijven leeg en de overige kaarten schuiven niet op.':['welcome','visitors'].includes(f.id)?'Het bezoekende team en zijn logo staan centraal; de volledige wedstrijd staat er apart bij. Maximaal vier aankomende eigen thuiswedstrijden, op aftraptijd.':f.id.includes('standings')||f.id==='matchday'?'Duindorp beweegt mee en stopt aan de boven- of onderrand. De overige teams blijven rustig doorscrollen.':f.description;$('#motion').innerHTML=icon(state.motion?'pause':'play');$('#motion').setAttribute('aria-label',state.motion?'Animaties pauzeren':'Animaties afspelen');$('#motion-label').textContent=state.motion?'Beweging aan':'Beweging gepauzeerd';$('#score-actions').hidden=!['scoreboard','goal'].includes(state.id);$('#welcome-preview-toolbar').hidden=!['welcome','visitors'].includes(state.id);$('#grid-preview-toolbar').hidden=!['birthdays','activities','agenda'].includes(state.id);if(['birthdays','activities','agenda'].includes(state.id)){$('#grid-count').value=String(state.gridCounts[state.id]);$('#grid-preview-label').textContent=f.id==='birthdays'?'Verjaardagen in voorbeeld':'Activiteiten in voorbeeld';}$$('[data-welcome-count]').forEach(b=>{const active=+b.dataset.welcomeCount===state.welcomeCount;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('#welcome-layout-label').textContent=({1:'Eén wedstrijd · één grote kaart',2:'Twee wedstrijden · twee ruime kaarten',3:'Drie wedstrijden · één grote en twee compacte kaarten',4:'Vier wedstrijden · een overzichtelijk raster'})[state.welcomeCount];for(const [id,active]of [['light',state.theme==='light'],['dark',state.theme==='dark'],['landscape',!state.portrait],['portrait',state.portrait]]){$('#'+id).classList.toggle('active',active);$('#'+id).setAttribute('aria-pressed',active)}renderSidebar();renderFilmstrip();scale();fitScene();requestAnimationFrame(fitScene);screen.querySelectorAll('img').forEach(img=>{if(!img.complete)img.addEventListener('load',fitScene,{once:true})});document.fonts.ready.then(fitScene);beginMotion();persist();document.title=`${f.name} · VeyoCast × OnzeTrots`}
function selectFamily(id){state.id=id;history.replaceState(null,'','#'+id);render();if($('#catalog-dialog').open)$('#catalog-dialog').close()}
function next(dir=1){const idx=families.findIndex(f=>f.id===state.id);selectFamily(families[(idx+dir+families.length)%families.length].id)}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function playCollection(){clearInterval(cycleTimer);if(state.playlist)cycleTimer=setInterval(()=>{if(state.motion&&document.visibilityState==='visible')next()},15000)}
function bind(){$('#slide-subtitle-text').oninput=e=>{state.headerSubtitles[state.id]=e.target.value.slice(0,120);$('#slide-subtitle').textContent=state.headerSubtitles[state.id];fitHeaderText();persist()};$('#slide-header-text').oninput=e=>{state.headerTexts[state.id]=e.target.value.slice(0,120);$('#slide-title').textContent=state.headerTexts[state.id];fitHeaderText();persist()};$('#header-reset').onclick=()=>{delete state.headerTexts[state.id];delete state.headerSubtitles[state.id];const f=families.find(f=>f.id===state.id);$('#slide-header-text').value=currentHeaderText(f);$('#slide-title').textContent=currentHeaderText(f);$('#slide-subtitle-text').value=currentHeaderSubtitle(f);$('#slide-subtitle').textContent=currentHeaderSubtitle(f);fitHeaderText();persist();toast('Standaard kop en subtitel hersteld')};$('#welcome-scale').oninput=e=>{state.welcomeScale=Math.max(100,Math.min(200,Number(e.target.value)||150));$('#welcome-scale-value').textContent=state.welcomeScale+'%';$('#screen').style.setProperty('--welcome-scale',state.welcomeScale/100);fitWelcomeIdentity();persist()};document.addEventListener('click',e=>{const b=e.target.closest('[data-family]');if(b)selectFamily(b.dataset.family);const preview=e.target.closest('[data-welcome-count]');if(preview){state.welcomeCount=+preview.dataset.welcomeCount;render(false)}const v=e.target.closest('[data-vote]');if(v){state.vote=+v.dataset.vote;render(false);toast('Voorbeeldstem verwerkt')}});$('#filters').onclick=e=>{const b=e.target.closest('[data-group]');if(b){state.group=b.dataset.group;renderSidebar()}};$('#search').oninput=e=>{state.query=e.target.value;renderSidebar()};$('#light').onclick=()=>{state.theme='light';render(false)};$('#dark').onclick=()=>{state.theme='dark';render(false)};$('#portrait').onclick=()=>{state.portrait=true;render(false)};$('#landscape').onclick=()=>{state.portrait=false;render(false)};$('#settings-button').onclick=()=>{const p=$('#settings-panel');p.hidden=!p.hidden;$('#settings-button').setAttribute('aria-expanded',!p.hidden)};$('#grid-count').onchange=e=>{if(['birthdays','activities','agenda'].includes(state.id)){state.gridCounts[state.id]=+e.target.value;render(false)}};$('#background').value=state.background;$('#background').onchange=e=>{state.background=e.target.value;render(false)};$('#opacity').value=state.opacity;$('#opacity-value').textContent=state.opacity+'%';$('#opacity').oninput=e=>{state.opacity=+e.target.value;$('#opacity-value').textContent=e.target.value+'%';$('#screen').style.setProperty('--panel',state.theme==='light'?`rgba(255,255,255,${state.opacity/100})`:`rgba(12,31,58,${state.opacity/100})`);persist()};$('#speed').value=state.speed;$('#speed').onchange=e=>{state.speed=e.target.value;beginMotion();persist()};$('#own-position').onchange=e=>{state.ownPosition=+e.target.value;render(false)};$('#playlist').onchange=e=>{state.playlist=e.target.value==='auto';playCollection();toast(state.playlist?'De hele collectie speelt af · 15 seconden per slide':'Geselecteerde slide blijft in beeld')};$('#motion').onclick=()=>{state.motion=!state.motion;if(!state.motion)$('#screen').classList.add('intro-finished');$('#screen').classList.toggle('is-paused',!state.motion);$('#motion').innerHTML=icon(state.motion?'pause':'play');$('#motion').setAttribute('aria-label',state.motion?'Animaties pauzeren':'Animaties afspelen');$('#motion-label').textContent=state.motion?'Beweging aan':'Beweging gepauzeerd'};$('#next').onclick=()=>next();$('#prev').onclick=()=>next(-1);$('#replay').onclick=replayScene;$('#presentation-replay').onclick=replayScene;$('#fullscreen').onclick=()=>{const dock=$('#stage-dock');dock.classList.add('presentation-fallback');document.body.classList.add('presenting');scale();if(dock.requestFullscreen&&document.fullscreenEnabled)dock.requestFullscreen().catch(()=>{})};$('#exit-fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();$('#stage-dock').classList.remove('presentation-fallback');document.body.classList.remove('presenting');scale()};$('#catalog-button').onclick=()=>{$('#catalog-grid').innerHTML=families.map(thumbnail).join('');$('#catalog-dialog').showModal()};$('#about').onclick=()=>$('#about-dialog').showModal();$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#score-goal').onclick=()=>{state.homeScore++;selectFamily('goal');toast('Voorbeelddoelpunt · Duindorp '+state.homeScore+'–'+state.awayScore)};$('#score-reset').onclick=()=>{state.homeScore=2;state.awayScore=1;render(false);toast('Voorbeeldscore teruggezet naar 2–1')};$('#match-moment').onchange=e=>{state.moment=e.target.value;selectFamily('scoreboard')};document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('dialog[open]'))return;if(e.key==='Escape'&&$('#stage-dock').classList.contains('presentation-fallback')){$('#exit-fullscreen').click();return}if(e.key==='ArrowRight'){e.preventDefault();next()}if(e.key==='ArrowLeft'){e.preventDefault();next(-1)}if(e.key===' '){e.preventDefault();$('#motion').click()}if(e.key==='/'){e.preventDefault();$('#search').focus()}});window.addEventListener('hashchange',()=>{state.id=location.hash.slice(1);render()});new ResizeObserver(()=>{scale();fitScene()}).observe($('#screen-shell'));document.addEventListener('fullscreenchange',scale);matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{state.motion=!e.matches;render(false)})}
async function init(){setIcons();try{const [catalog,logoResponse]=await Promise.all([fetch('/repo-inventory.json').then(r=>r.json()),fetch('/assets/club-logos.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]);families=catalog.families;logos=logoResponse;bind();render()}catch(e){$('#screen').innerHTML='<div style="padding:50px;color:#102441">De collectie kon niet worden geladen. Vernieuw de pagina om opnieuw te proberen.</div>';console.error(e)}}
init();
